;font-weight:800}.profile b,.profile small{display:block}.profile b{font-size:11px}.profile small{font-size:8px;color:var(--muted);margin-top:3px;letter-spacing:.8px}.chevron{color:var(--muted);margin-left:7px}main{padding:30px clamp(20px,4vw,62px) 25px}.view{display:none;animation:fade .25s ease}.view.active{display:block}@keyframes fade{from{opacity:.55;transform:translateY(4px)}to{opacity:1;transform:none}}.battle-heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px}.eyebrow{font-family:'Space Grotesk';font-size:9px;letter-spacing:1.6px;color:var(--gold);font-weight:700;display:flex;gap:8px;align-items:center}.live-dot{height:6px;width:6px;border-radius:50%;background:#76d3a9;box-shadow:0 0 9px #76d3a9}.battle-heading h1,.page-heading h1{font:700 29px 'Space Grotesk';letter-spacing:-.8px;margin:6px 0 1px}.battle-heading h1 em{font-style:normal;color:#686e82;font-size:20px}.battle-heading p,.page-heading p{margin:0;color:var(--muted);font-size:12px}.power-pill{display:flex;align-items:center;gap:10px;border:1px solid var(--line);background:var(--panel);border-radius:10px;padding:9px 14px}.power-pill>span{font-size:21px;color:var(--gold)}.power-pill small,.power-pill b{display:block}.power-pill small{font-size:8px;color:var(--muted);letter-spacing:1px}.power-pill b{font:600 14px 'Space Grotesk';margin-top:2px}.battle-layout{display:grid;grid-template-columns:minmax(0,1fr) 310px;gap:15px}.arena-wrap{min-width:0}.arena{height:440px;border:1px solid #34374a;border-radius:13px;overflow:hidden;position:relative;background:linear-gradient(180deg,#27304c 0%,#302c43 51%,#55404a 100%);box-shadow:0 18px 50px #0003}.arena-sky{position:absolute;inset:0;overflow:hidden;background:radial-gradient(ellipse at 68% 20%,#f7965940 0,transparent 33%),linear-gradient(180deg,#202a45 0%,#35364d 56%,#70514d 100%)}.planet{position:absolute;width:135px;height:135px;right:17%;top:32px;border-radius:50%;background:radial-gradient(circle at 35% 33%,#ffc078,#ce665c 45%,#793d59 75%);box-shadow:0 0 68px #f07b6966;opacity:.72}.stars{position:absolute;inset:0;background-image:radial-gradient(1px 1px at 12% 21%,#fff 98%,transparent),radial-gradient(1px 1px at 43% 17%,#fff 98%,transparent),radial-gradient(1px 1px at 88% 31%,#fff 98%,transparent),radial-gradient(1px 1px at 74% 11%,#fff 98%,transparent),radial-gradient(1px 1px at 28% 42%,#fff 98%,transparent);opacity:.6}.distant-city{position:absolute;height:106px;bottom:67px;left:0;right:0;opacity:.7;background:linear-gradient(0deg,#23283b,#23283b) 0 70%/100% 30%,linear-gradient(90deg,transparent 0 4%,#31334a 4% 8%,transparent 8% 11%,#292e44 11% 15%,transparent 15% 19%,#34354b 19% 23%,transparent 23% 27%,#272c42 27% 32%,transparent 32% 38%,#33334a 38% 42%,transparent 42% 46%,#272d43 46% 52%,transparent 52% 56%,#303249 56% 61%,transparent 61% 65%,#282d42 65% 70%,transparent 70% 73%,#34344a 73% 80%,transparent 80% 85%,#282d43 85% 91%,transparent 91%) bottom/100% 100% no-repeat;clip-path:polygon(0 35%,5% 35%,5% 4%,8% 4%,8% 45%,13% 45%,13% 24%,17% 24%,17% 50%,22% 50%,22% 13%,25% 13%,25% 43%,30% 43%,30% 30%,34% 30%,34% 50%,40% 50%,40% 15%,43% 15%,43% 48%,50% 48%,50% 28%,55% 28%,55% 49%,61% 49%,61% 7%,65% 7%,65% 44%,70% 44%,70% 22%,75% 22%,75% 50%,82% 50%,82% 11%,87% 11%,87% 43%,94% 43%,94% 28%,100% 28%,100% 100%,0 100%)}.arena-top{position:absolute;top:14px;left:16px;right:16px;display:flex;justify-content:space-between;z-index:2}.wave-chip,.speed-btn{background:#10131eaa;border:1px solid #ffffff20;backdrop-filter:blur(8px);border-radius:7px;padding:7px 10px;font-size:9px;letter-spacing:.7px}.wave-chip span{color:var(--gold);margin-right:5px}.wave-chip b{color:#fff}.wave-chip small{color:#a7a5ae;margin-left:3px}.speed-btn{color:#d8d8e2;cursor:pointer}.speed-btn span{color:var(--gold);margin-left:5px}.battlefield{position:absolute;left:4%;right:4%;top:69px;bottom:88px;display:flex;align-items:center;justify-content:space-between}.team{width:42%;height:100%;display:flex;align-items:flex-end;justify-content:center;gap:clamp(0px,1vw,12px);position:relative}.team-enemy{align-items:center;transform:translateY(-8px)}.arena-vs{font:700 16px 'Space Grotesk';font-style:italic;color:#fff8;align-self:center;text-shadow:0 2px 6px #000}.battle-unit{--unit:#5387e8;position:relative;width:18%;max-width:98px;min-width:54px;height:190px;display:flex;flex-direction:column;justify-content:flex-end;align-items:center;filter:drop-shadow(0 8px 8px #1119);transition:transform .3s}.team-enemy .battle-unit{height:154px;width:23%;max-width:105px;min-width:62px;transform:scaleX(-1)}.battle-unit .unit-glow{position:absolute;inset:24% -5px 8%;border-radius:50%;background:radial-gradient(ellipse,#f4a16a38,transparent 70%);z-index:0}.figure{position:relative;width:78%;height:74%;z-index:1;display:flex;flex-direction:column;align-items:center;justify-content:flex-end}.cape{position:absolute;bottom:2%;height:78%;width:82%;background:var(--unit);clip-path:polygon(15% 0,85% 0,100% 100%,0 100%);filter:brightness(.62);border-radius:13px 13px 5px 5px}.head{position:absolute;top:5%;width:32%;aspect-ratio:1;border-radius:45% 45% 43% 43%;background:linear-gradient(140deg,#ffe1c1,#bb8e78);z-index:2;border:2px solid #25283a}.mask{position:absolute;top:12%;width:42%;height:15%;border-radius:50%;background:var(--unit);z-index:3;opacity:.98}.body-suit{position:absolute;bottom:0;width:74%;height:70%;border-radius:24px 24px 8px 8px;background:linear-gradient(110deg,var(--unit),color-mix(in srgb,var(--unit),#111 28%));clip-path:polygon(25% 0,75% 0,100% 18%,88% 100%,12% 100%,0 18%);z-index:1}.emblem{position:absolute;z-index:4;bottom:37%;font-size:clamp(12px,1.7vw,21px);font-weight:900;color:#fff;text-shadow:0 1px 3px #0009}.unit-name{position:relative;z-index:3;font-size:9px;font-weight:800;text-shadow:0 1px 5px #000;white-space:nowrap;margin:5px 0 5px}.health-track{position:absolute;top:-15px;left:2px;right:2px;height:5px;background:#1a1b29;border-radius:9px;overflow:hidden;z-index:4}.health-track i{height:100%;display:block;background:linear-gradient(90deg,#61d3a4,#a6db8b);border-radius:9px;transition:width .4s}.team-enemy .health-track i{background:linear-gradient(90deg,#e85e58,#f5ab63)}.battle-unit.attacking{animation:attack .35s ease}.battle-unit.hit{animation:hit .3s ease}@keyframes attack{45%{transform:translateX(24px) scale(1.05)}}@keyframes hit{25%{filter:brightness(2) drop-shadow(0 0 13px #fa5)}}.team-enemy .battle-unit.attacking{animation:enemyAttack .35s ease}@keyframes enemyAttack{45%{transform:translateX(-20px) scaleX(-1) scale(1.05)}}.arena-bottom{height:68px;position:absolute;bottom:0;left:0;right:0;background:linear-gradient(0deg,#111522f5,#191d2ad9);border-top:1px solid #ffffff17;z-index:2;display:flex;align-items:center;justify-content:space-between;padding:0 16px}.battle-log{min-width:0;color:#d4d4de;font-size:10px;display:flex;align-items:center;gap:8px}.battle-log>span:last-child{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.log-dot{width:6px;height:6px;background:var(--gold);border-radius:50%;box-shadow:0 0 8px var(--gold)}.battle-controls{display:flex;gap:8px;flex-shrink:0}.auto-toggle,.ultimate-btn{height:34px;border-radius:7px;padding:0 10px;background:#ffffff0c;color:#c5c6d0;font-size:9px;letter-spacing:.6px;display:flex;align-items:center;gap:7px;border:1px solid #ffffff16}.toggle-dot{width:8px;height:8px;border-radius:50%;background:#777}.auto-toggle.on .toggle-dot{background:#75d0a6;box-shadow:0 0 8px #75d0a6}.ultimate-btn{background:#9e4f43;color:#fff;border-color:#ee907760}.ultimate-btn>span{color:#ffd58b;font-size:14px}.ultimate-btn kbd{font-size:8px;padding:2px 4px;background:#ffffff20;border-radius:3px;color:#ffd9c6}.combat-flash{position:absolute;inset:0;pointer-events:none;z-index:3}.combat-flash.flash{animation:flash .4s ease}@keyframes flash{0%{background:#fff0}22%{background:#f9d77c36}100%{background:#fff0}}.stage-footer{height:36px;display:flex;align-items:center;justify-content:space-between;color:#9298aa;font-size:10px;padding:0 3px}.stage-footer>div{display:flex;align-items:center;gap:7px}.stage-footer b{color:#fff;font-weight:600}.check-icon{display:grid;place-items:center;width:16px;height:16px;border-radius:50%;background:#72c9a31c;color:#78d5aa;font-size:10px}.text-button{background:none;color:var(--gold);font:700 9px 'Space Grotesk';letter-spacing:.7px}.text-button span{font-size:16px;margin-left:4px}
