const uniqueNames = [...new Set(rosterNames)];
const colors = ['#4979d5','#c64851','#47a8ba','#9467c8','#5bb38a','#dc8549','#d1ad48','#cf6088','#7486d5','#6a99a8','#d35f43','#87a34a'];
const symbols = ['S','B','✦','⚡','◈','A','✧','☼','◉','♦','✹','⚔'];
const villains = new Set(['Coringa','Lex Luthor','Darkseid','Doomsday','Arlequina','Mulher-Gato','Charada','Pinguim','Duas-Caras','Bane','Espantalho','Sr. Frio','Hera Poison','Hera Venenosa','Exterminador','Sinestro','Brainiac','General Zod','Black Adam','Circe','Ares','Cheetah','Manta Negra','Ocean Master','Gorila Grodd','Capitão Frio','Mestre dos Espelhos','Zoom','Reverse-Flash','Savitar','Flash Reverso','Parasita','Metallo','Bizarro','Livewire','Despero','Starro','Vandal Savage','Ra\'s al Ghul','Hush','Máscara Negra','Silêncio','Trigon','Anti-Monitor','Superboy-Prime','Sinestro (amarelo)','Lobo','Mongul']);
const ownedStarter = ['Superman','Batman','Mulher-Maravilha','Flash','Lanterna Verde'];
const levels = {Superman:12,Batman:11,'Mulher-Maravilha':10,Flash:9,'Lanterna Verde':9};
const rarityList=['LENDÁRIO','ÉPICO','RARO','RARO','COMUM'];
const cast = uniqueNames.slice(0,320).map((name,i)=>({id:i,name,role:villains.has(name)|| /Coringa|Luthor|Darkseid|Doomsday|Brainiac|Grodd|Thawne|Manta|Crocodilo|Frio|Sinestro|Bane|Charada|Grundy|Mongul|Trigon|Anti-Monitor|Ultraman|Owlman|Joker|Black Adam|Cheetah|Starro|Poison|Hera|Lex|Zoom|Exterminador|Zod|Parasita|Metallo|Bizarro|Vandal|Ra's|Hush|Silêncio|Deathstroke|Nekron|Parallax|Mister Freeze|Livewire|Savitar|Superboy-Prime|The Drowned|Merciless|Devastator/i.test(name)?'Vilão':'Herói', color:colors[i%colors.length],symbol:symbols[i%symbols.length],rarity:i<5?'LENDÁRIO':rarityList[i%rarityList.length],power:1250+(i*137)%1650,level:levels[name]||1,owned:ownedStarter.includes(name)}));
if(cast.length<320){const fillers=['Kestrel','Nightblade','Solaris','Tempest','Valkyrie','Red Talon','The Sentinel','Starhawk','Phantom Knight','Ironclad','Blackout','Dreadnought','Silver Arrow','The Beacon','Nightshade','Sunburst','Thunderstrike','Moonstone','Firebrand','The Warden','Shadowstar','Crimson Fox','Rift','Nova Prime','Wildfire','Skyguard','Darkstar','The Outrider','Stormwatch','Eclipse'];for(let i=cast.length;i<320;i++){let name=`${fillers[i%fillers.length]} ${Math.floor(i/fillers.length)+1}`;cast.push({id:i,name,role:i%4===0?'Vilão':'Herói',color:colors[i%colors.length],symbol:symbols[i%symbols.length],rarity:rarityList[i%rarityList.length],power:1250+(i*137)%1650,level:1,owned:false})}}

const state={gold:1250,gems:120,sector:7,stage:12,wave:1,auto:true,speed:1,battleActive:false,filter:'Todos',query:'',earnedBattles:1,missions:[false,false,false],claimedDaily:false,claimedObjective:false,idleSeconds:0,lastSave:Date.now(), lastIdle:Date.now(), selected:'Superman', party:ownedStarter.slice(), combatTimer:null, toastTimer:null};
const enemySet=[{name:'Parademônio',color:'#9b5565',symbol:'◈',hp:100},{name:'Lobo da Estepe',color:'#a76d52',symbol:'⚔',hp:150},{name:'Desaad',color:'#77669d',symbol:'◉',hp:130}];
const stages=['A invasão de Apokolips','Sombras sobre Gotham','O último sinal de Oa','A queda de Metrópolis','O mundo de Bizarro','A guerra das lanternas'];
let enemyHP=[100,100,100];
const $=s=>document.querySelector(s);
function number(n){return Math.floor(n).toLocaleString('pt-BR')}
function escapeHTML(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function hero(name){return cast.find(h=>h.name===name)||cast[0]}
function say(text){const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>el.classList.remove('show'),2300)}
function log(text){$('#logText').textContent=text}
function save(){state.lastSave=Date.now();localStorage.setItem('criseInfinitaSave',JSON.stringify({...state,combatTimer:undefined,toastTimer:undefined}))}
function load(){try{const d=JSON.parse(localStorage.getItem('criseInfinitaSave'));if(d){Object.assign(state,d);state.battleActive=false;state.auto=d.auto!==false;state.party=(d.party||ownedStarter).filter(n=>hero(n));state.idleSeconds=Math.max(0,d.idleSeconds||0);const elapsed=Math.min(28800,Math.floor((Date.now()-(d.lastIdle||Date.now()))/1000));if(elapsed>0){state.idleSeconds+=elapsed;state.gold+=Math.floor(elapsed/90);}}}catch(e){console.warn('Save local inválido',e)}}
function go(view){document.querySelectorAll('.view').forEach(x=>x.classList.toggle('active',x.id===view+'View'));document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.view===view));window.scrollTo({top:0,behavior:'smooth'});if(view==='heroes')renderRoster();if(view==='missions')renderMissions();}
function renderResources(){$('#gold').textContent=number(state.gold);$('#gems').textContent=number(state.gems);$('#sector').textContent=String(state.sector).padStart(2,'0');$('#stage').textContent=state.stage;$('#stageName').textContent=stages[(state.stage-1)%stages.length];$('#wave').textContent=state.wave;$('#playerLevel').textContent=12+Math.floor(state.earnedBattles/5);$('#teamPower').textContent=number(state.party.reduce((n,id)=>n+hero(id).power*hero(id).level,0));$('#ownedCount').textContent=cast.filter(h=>h.owned).length;$('#rosterCount').textContent=cast.length;$('#objectiveCount').textContent=`${Math.min(3,state.earnedBattles)}/3`;$('#objectiveProgress').style.width=`${Math.min(100,state.earnedBattles/3*100)}%`;$('#battleButtonText').textContent=state.battleActive?'COMBATE EM ANDAMENTO':'INICIAR BATALHA';$('#speedLabel').textContent=`${state.speed}×`}
function avatar(h,withMask=true){return `<span class="portrait" style="--unit:${h.color}"><i></i><b>${escapeHTML(h.symbol)}</b></span>`}
function renderSquad(){const list=$('#squadList');list.innerHTML=state.party.map((name,i)=>{const h=hero(name);return `<div class="squad-row" data-hero="${h.id}">${avatar(h)}<div class="squad-info"><b>${escapeHTML(h.name)}</b><small><span>NV. ${h.level}</span> · ${i===0?'Lendário':h.rarity.toLowerCase()}</small></div><span class="role-symbol">${['✦','⚔','◈','⚡','✧'][i%5]}</span></div>`}).join('')}
function unit(h,enemy=false,index=0){return `<div class="battle-unit ${enemy?'enemy-unit':''}" data-index="${index}" style="--unit:${h.color}"><div class="unit-glow"></div><div class="figure"><div class="cape"></div><div class="body-suit"></div><div class="head"></div><div class="mask"></div><div class="emblem">${escapeHTML(h.symbol)}</div></div><div class="unit-name">${escapeHTML(h.name)}</div><div class="health-track"><i style="width:100%"></i></div></div>`}
function renderArena(){const enemyHTML=enemySet.map((e,i)=>unit(e,true,i)).join('');const playerHTML=state.party.slice(0,5).map((n,i)=>unit(hero(n),false,i)).join('');$('#enemyTeam').innerHTML=enemyHTML;$('#playerTeam').innerHTML=playerHTML;}
function renderRoster(){const list=$('#heroGrid');let items=cast.filter(h=>{let match=h.name.toLowerCase().includes(state.query.toLowerCase());let filter=state.filter==='Todos'||(state.filter==='Herói'&&h.role==='Herói')||(state.filter==='Vilão'&&h.role==='Vilão')||(state.filter==='Equipe'&&state.party.includes(h.name));return match&&filter});list.innerHTML=items.length?items.map(h=>`<article class="hero-card ${h.owned?'':'locked'}" data-hero="${h.id}" style="--unit:${h.color}"><div class="hero-art"><span class="rarity">${h.rarity}</span>${h.owned?'<span class="owned-mark">✓</span>':''}<span class="art-mask"></span><span class="art-symbol">${escapeHTML(h.symbol)}</span></div><div class="hero-copy"><b>${escapeHTML(h.name)}</b><small>${h.role} · ${h.owned?'Nível '+h.level:'Ainda não recrutado'}</small><div class="hero-power"><span>✦ ${number(h.power*h.level)}</span>${state.party.includes(h.name)?'<i>NA EQUIPE</i>':h.owned?'<i>DETALHES</i>':'<i>✧</i>'}</div></div></article>`).join(''):'<div class="empty-state">Nenhum personagem encontrado neste setor do multiverso.</div>';renderResources()}

