function renderRoster(){const list=$('#heroGrid');let items=cast.filter(h=>{let match=h.name.toLowerCase().includes(state.query.toLowerCase());let filter=state.filter==='Todos'||(state.filter==='Herói'&&h.role==='Herói')||(state.filter==='Vilão'&&h.role==='Vilão')||(state.filter==='Equipe'&&state.party.includes(h.name));return match&&filter});list.innerHTML=items.length?items.map(h=>`<article class="hero-card ${h.owned?'':'locked'}" data-hero="${h.id}" style="--unit:${h.color}"><div class="hero-art"><span class="rarity">${h.rarity}</span>${h.owned?'<span class="owned-mark">✓</span>':''}<span class="art-mask"></span><span class="art-symbol">${escapeHTML(h.symbol)}</span></div><div class="hero-copy"><b>${escapeHTML(h.name)}</b><small>${h.role} · ${h.owned?'Nível '+h.level:'Ainda não recrutado'}</small><div class="hero-power"><span>✦ ${number(h.power*h.level)}</span>${state.party.includes(h.name)?'<i>NA EQUIPE</i>':h.owned?'<i>DETALHES</i>':'<i>✧</i>'}</div></div></article>`).join(''):'<div class="empty-state">Nenhum personagem encontrado neste setor do multiverso.</div>';renderResources()}
function showModal(html){$('#modalContent').innerHTML=html;$('#modal').classList.add('open')}
function closeModal(){$('#modal').classList.remove('open')}
function heroDetails(h){state.selected=h.name;const inTeam=state.party.includes(h.name);let action=h.owned?`<div class="modal-actions">${inTeam?'<button class="secondary-btn" data-action="removeHero">TIRAR DA EQUIPE</button>':`<button class="secondary-btn" data-action="addHero">${state.party.length<5?'ADICIONAR À EQUIPE':'SUBSTITUIR NA EQUIPE'}</button>`}<button class="primary-btn" data-action="upgrade">EVOLUIR · ${number(250*h.level)} ◈</button></div>`:`<button class="primary-btn" data-action="summon">RECRUTAR · 1.000 ◈</button>`;showModal(`<div class="eyebrow">${h.rarity} · ${h.role.toUpperCase()}</div><div class="modal-hero">${avatar(h)}<div><h2>${escapeHTML(h.name)}</h2><p>${inTeam?'Membro da formação ativa.':'Um poderoso aliado espera seu chamado.'}</p></div></div><div class="modal-stats"><div><small>PODER</small><b>✦ ${number(h.power*h.level)}</b></div><div><small>NÍVEL</small><b>${h.owned?h.level:'—'}</b></div></div>${action}`)}
function renderMissions(){const missions=[['⚔','Vitória da Liga','Conclua 3 batalhas na campanha.','500 ouro',state.earnedBattles>=3,0],['✦','Poder crescente','Evolua um personagem do seu esquadrão.','50 cristais',state.party.some(n=>hero(n).level>levels[n]),1],['◎','Recrutador','Adicione 2 novos personagens à coleção.','750 ouro',cast.filter(h=>h.owned).length>=7,2]];$('#missionList').innerHTML=missions.map((m,i)=>`<article class="mission-card"><div class="mission-icon">${m[0]}</div><h3>${m[1]}</h3><p>${m[2]}</p><div class="mission-reward"><span>✧ ${m[3]}</span><button data-action="claimMission" data-index="${i}" ${state.missions[i]||!m[4]?'disabled':''}>${state.missions[i]?'RESGATADA':m[4]?'RESGATAR':'EM PROGRESSO'}</button></div></article>`).join('')}
function animateUnit(selector,index,kind='attacking'){const el=document.querySelectorAll(selector)[index];if(!el)return;el.classList.remove(kind);void el.offsetWidth;el.classList.add(kind);setTimeout(()=>el.classList.remove(kind),400)}
function updateHealth(){document.querySelectorAll('#enemyTeam .battle-unit').forEach((el,i)=>{const hp=enemyHP[i]||0;const max=enemySet[i].hp;el.style.opacity=hp<=0?'.16':'1';el.querySelector('.health-track i').style.width=`${Math.max(0,hp/max*100)}%`})}
function playerTurn(ultimate=false){if(!state.battleActive){startBattle();return}let alive=enemyHP.map((v,i)=>v>0?i:-1).filter(i=>i>=0);if(!alive.length){finishWave();return}let targets=ultimate?alive: [alive[Math.floor(Math.random()*alive.length)]];let damage=ultimate?58+Math.floor(Math.random()*38):28+Math.floor(Math.random()*22);targets.forEach((i,j)=>{enemyHP[i]=Math.max(0,enemyHP[i]-damage);animateUnit('#enemyTeam .battle-unit',i,'hit')});const actor=hero(state.party[Math.floor(Math.random()*state.party.length)]);log(ultimate?`${actor.name} libera seu poder supremo!`:`${actor.name} ataca os invasores!`);if(ultimate){const flash=$('#combatFlash');flash.classList.remove('flash');void flash.offsetWidth;flash.classList.add('flash')}updateHealth();if(enemyHP.every(v=>v<=0)){setTimeout(finishWave,450)}else if(state.auto){setTimeout(enemyTurn,420)}}
function enemyTurn(){if(!state.battleActive)return;let i=Math.floor(Math.random()*state.party.length);animateUnit('#playerTeam .battle-unit',i,'hit');const target=state.party[i];log(`${enemySet[Math.floor(Math.random()*enemySet.length)].name} atinge ${target}!`);if(state.auto)setTimeout(()=>playerTurn(false),650)}
function startBattle(){if(state.battleActive){if(!state.auto)playerTurn();return}state.battleActive=true;state.wave=1;enemyHP=enemySet.map(e=>e.hp);renderArena();renderResources();log('A batalha começou. Defenda a Terra!');if(state.auto)playerTurn();say('Batalha iniciada!')}
function finishWave(){if(!state.battleActive)return;if(state.wave<3){state.wave++;enemyHP=enemySet.map(e=>e.hp+state.wave*15);$('#wave').textContent=state.wave;renderArena();log(`Onda ${state.wave}: novos inimigos chegaram!`);setTimeout(()=>{if(state.battleActive&&state.auto)playerTurn()},450)}else completeBattle()}
function completeBattle(){state.battleActive=false;state.stage++;if(state.stage>15){state.sector++;state.stage=1}state.earnedBattles++;const reward=240+state.stage*22;state.gold+=reward;state.gems+=3;state.wave=1;renderResources();renderArena();log('Vitória! A Liga protegeu o multiverso.');save();showModal(`<div class="combat-result"><div class="result-icon">✦</div><div class="eyebrow" style="justify-content:center">MISSÃO CONCLUÍDA</div><h2>Vitória da Liga!</h2><p>Seu esquadrão afastou as forças de Apokolips.</p><div class="reward-line">◈ +${number(reward)} ouro &nbsp; · &nbsp; ◆ +3 cristais</div><button class="primary-btn" data-action="closeModal">CONTINUAR</button></div>`)}
function collectIdle(){const time=state.idleSeconds;const reward=Math.floor(time/90)+Math.max(0,Math.floor((Date.now()-state.lastIdle)/90000));state.idleSeconds=0;state.lastIdle=Date.now();if(reward>0){state.gold+=reward;renderResources();save();say(`Recompensa AFK coletada: +${number(reward)} ouro!`)}else say('Sua recompensa AFK ainda está acumulando. Volte em breve!')}
function summon(){if(state.gold<1000){say('Ouro insuficiente. Complete batalhas para ganhar mais!');closeModal();return}const candidates=cast.filter(h=>!h.owned);if(!candidates.length){say('Você já recrutou todos os personagens!');closeModal();return}state.gold-=1000;let pick=candidates[Math.floor(Math.random()*candidates.length)];pick.owned=true;pick.level=1;renderResources();renderRoster();save();showModal(`<div class="combat-result"><div class="result-icon" style="color:${pick.color}">${escapeHTML(pick.symbol)}</div><div class="eyebrow" style="justify-content:center">NOVO RECRUTAMENTO</div><h2>${escapeHTML(pick.name)}</h2><p>${pick.role} · ${pick.rarity}. Um novo aliado se junta à sua coleção!</p><div class="reward-line">✦ Poder ${number(pick.power)} &nbsp; · &nbsp; Nível 1</div><button class="primary-btn" data-action="closeModal">BEM-VINDO À LIGA</button></div>`)}
function claimMission(index){if(state.missions[index])return;const can=[state.earnedBattles>=3,state.party.some(n=>hero(n).level>(levels[n]||1)),cast.filter(h=>h.owned).length>=7][index];if(!can){say('Missão ainda não concluída.');return}state.missions[index]=true;if(index===1)state.gems+=50;else state.gold+=index===0?500:750;renderMissions();renderResources();save();say('Recompensa da missão coletada!')}

