das batalhas e missões.'} Ganhe mais completando campanhas e coletando recompensas AFK.</p><div class="reward-line">◈ ${number(state.gold)} ouro &nbsp; · &nbsp; ◆ ${number(state.gems)} cristais</div><button class="primary-btn" data-action="closeModal">ENTENDI</button>`);break;case 'objective':if(state.earnedBattles>=3&&!state.claimedObjective){state.claimedObjective=true;state.gold+=350;renderResources();save();say('Objetivo diário concluído! +350 ouro.')}else say(state.claimedObjective?'Objetivo diário já resgatado.':'Complete 3 batalhas para concluir o objetivo.');break;case 'event':showModal('<div class="eyebrow">EVENTO TEMPORÁRIO · 2D 14H</div><h2>Crise nas Terras Infinitas</h2><p>Uma ruptura entre dimensões ameaça todas as Terras. Prepare seu esquadrão e avance pela campanha para encontrar a origem da crise.</p><div class="reward-line">Recompensas especiais · Personagens épicos</div><button class="primary-btn" data-action="closeModal">PREPARAR EQUIPE</button>');break;case 'profile':showModal(`<div class="eyebrow">COMANDANTE DA LIGA</div><h2>Parceiro</h2><p>Nível ${12+Math.floor(state.earnedBattles/5)} · Progresso salvo neste dispositivo.</p><div class="modal-stats"><div><small>BATALHAS VENCIDAS</small><b>${state.earnedBattles}</b></div><div><small>PERSONAGENS</small><b>${cast.filter(h=>h.owned).length} / ${cast.length}</b></div></div><button class="primary-btn" data-action="closeModal">CONTINUAR</button>`);break;case 'claimMission':claimMission(Number(button.dataset.index));break}}
document.addEventListener('click',e=>{const view=e.target.closest('[data-view]');if(view){go(view.dataset.view);return}const action=e.target.closest('[data-action]');if(action){performAction(action.dataset.action,action);return}const card=e.target.closest('[data-hero]');if(card){const h=cast[Number(card.dataset.hero)];if(h)heroDetails(h)}});
