function save(){
  state.lastSave=Date.now();
  // Squad membership is authoritative: a hero in the active team must never
  // be written to disk as unowned, even if an older save was inconsistent.
  state.party.forEach(name=>{const h=cast.find(item=>item.name===name);if(h)h.owned=true});
  const data={...state,combatTimer:undefined,toastTimer:undefined,heroes:cast.map(({name,owned,level,power})=>({name,owned,level,power}))};
  localStorage.setItem('criseInfinitaSave',JSON.stringify(data));
}
function load(){
  try{
    const d=JSON.parse(localStorage.getItem('criseInfinitaSave'));
    if(!d)return;
    Object.assign(state,d);
    if(Array.isArray(d.heroes))d.heroes.forEach(saved=>{
      const h=cast.find(item=>item.name===saved.name);
      if(h){
        h.owned=saved.owned===true;
        h.level=Math.max(1,Number(saved.level)||1);
        h.power=Math.max(1,Number(saved.power)||h.power);
      }
    });
    const savedParty=Array.isArray(d.party)?d.party:ownedStarter;
    state.party=[...new Set(savedParty.filter(name=>cast.some(item=>item.name===name)))].slice(0,5);
    // Older or partially-written saves may have party membership without the
    // matching ownership flag. Reconcile it before the UI or next save runs.
    state.party.forEach(name=>{const h=cast.find(item=>item.name===name);if(h)h.owned=true});
    state.battleActive=false;
    state.auto=d.auto!==false;
    state.idleSeconds=Math.max(0,Number(d.idleSeconds)||0);
    const elapsed=Math.min(28800,Math.floor((Date.now()-(d.lastSave||Date.now()))/1000));
    if(elapsed>0)state.idleSeconds+=elapsed;
    state.lastIdle=Date.now();
  }catch(e){console.warn('Save local inválido',e)}
}

