 function animateUnit(selector,index,kind='attacking'){const el=document.querySelectorAll(selector)[index];if(!el)return;el.classList.remove(kind);void el.offsetWidth;el.classList.add(kind);setTimeout(()=>el.classList.remove(kind),400)}
 function updateHealth(){document.querySelectorAll('#enemyTeam .battle-unit').forEach((el,i)=>{const hp=enemyHP[i]||0;const max=enemySet[i].hp;el.style.opacity=hp<=0?'.16':'1';el.querySelector('.health-track i').style.width=`${Math.max(0,hp/max*100)}%`})}
 function playerTurn(ultimate=false){if(!state.battleActive){startBattle();return}let alive=enemyHP.map((v,i)=>v>0?i:-1).filter(i=>i>=0);if(!alive.length){finishWave();return}let targets=ultimate?alive: [alive[Math.floor(Math.random()*alive.length)]];let damage=ultimate?58+Math.floor(Math.random()*38):28+Math.floor(Math.random()*22);targets.forEach((i,j)=>{enemyHP[i]=Math.max(0,enemyHP[i]-damage);animateUnit('#enemyTeam .battle-unit',i,'hit')});const actor=hero(state.party[Math.floor(Math.random()*state.party.length)]);log(ultimate?`${actor.name} libera seu poder supremo!`:`${actor.name} ataca os invasores!`);if(ultimate){const flash=$('#combatFlash');flash.classList.remove('flash');void flash.offsetWidth;flash.classList.add('flash')}updateHealth();if(enemyHP.every(v=>v<=0)){setTimeout(finishWave,450)}else if(state.auto){setTimeout(enemyTurn,Math.max(180,420/state.speed))}}
 function enemyTurn(){if(!state.battleActive)return;let i=Math.floor(Math.random()*state.party.length);animateUnit('#playerTeam .battle-unit',i,'hit');const target=state.party[i];log(`${enemySet[Math.floor(Math.random()*enemySet.length)].name} atinge ${target}!`);if(state.auto)setTimeout(()=>playerTurn(false),Math.max(180,650/state.speed))}
